def crop_nonbg(A, bg):
    A=np.array(A); h,w=A.shape
    # rows/cols that contain at least one non-bg cell
    rm=[r for r in range(h) if any(A[r]!=bg)]
    cm=[c for c in range(w) if any(A[:,c]!=bg)]
    return A[min(rm):max(rm)+1, min(cm):max(cm)+1] if rm and cm else A

