def tile_of(I, excl):
    A=np.array(I); H,W=A.shape; res=[]
    for p in range(1,H+1):
        for q in range(1,W+1):
            tbl={}; ok=True
            for r in range(H):
                for c in range(W):
                    if A[r,c] in excl: continue
                    k=(r%p,c%q)
                    if k in tbl and tbl[k]!=A[r,c]: ok=False;break
                    tbl[k]=A[r,c]
                if not ok:break
            if ok: res.append((p*q,p,q,tbl)); break
    return res

def solve(I):
    A=np.array(I); H,W=A.shape
    bg=int(Counter(A.flatten()).most_common(1)[0][0])
    excl=set(k for k in set(A.flatten())-{bg} if sum(A==k)<H*W//6)
    p,q,tbl=tile_of(A,excl)[0]
    g=A.copy()
    for r in range(H):
        for c in range(W):
            if A[r,c] in excl:
                g[r,c]=tbl[(r%p,c%q)]
    keep=[r for r in range(H) if any(g[r]!=bg)]
    if not keep: keep=list(range(H))
    kc=[c for c in range(W) if any(g[:,c]!=bg)]
    if not kc: kc=list(range(W))
    sub=g[min(keep):max(keep)+1,min(kc):max(kc)+1]
    return sub.tolist()

